<?php
namespace Tests\Feature;
use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Storage;use Illuminate\Http\UploadedFile;use App\Models\User;
class UmkmDisbursementFailureEvidenceTest extends TestCase {use RefreshDatabase;
 public function test_admin_records_private_failure_evidence_without_releasing_balance():void{Storage::fake('local');[$admin,$d,$e]=$this->fixture();Storage::disk('local')->put('original.pdf','old');$this->actingAs($admin)->patch(route('admin.disbursements.record-failure',$d),['reason'=>'Ditolak bank','transfer_reference'=>'REF-1','proof'=>UploadedFile::fake()->create('gagal.pdf',100,'application/pdf')])->assertRedirect();$d=$d->fresh();$this->assertSame('approved',$d->status);$this->assertSame($admin->id,$d->transfer_failure_recorded_by);$this->assertNotNull($d->transfer_failure_recorded_at);Storage::disk('local')->assertExists($d->transfer_failure_proof_path);Storage::disk('local')->assertExists('original.pdf');$this->assertSame('reserved',$e->fresh()->status);$this->assertDatabaseHas('umkm_disbursement_events',['umkm_disbursement_id'=>$d->id,'event_type'=>'failure_evidence_recorded']);}
 public function test_non_admin_and_invalid_upload_are_rejected():void{Storage::fake('local');[$admin,$d]=$this->fixture();$owner=$d->umkmStore->user;$this->actingAs($owner)->patch(route('admin.disbursements.record-failure',$d),['reason'=>'x','transfer_reference'=>'r','proof'=>UploadedFile::fake()->create('x.pdf',1,'application/pdf')])->assertForbidden();$this->actingAs($admin)->patch(route('admin.disbursements.record-failure',$d),['reason'=>'x','transfer_reference'=>'r','proof'=>UploadedFile::fake()->create('x.exe',1,'application/octet-stream')])->assertSessionHasErrors('proof');}
 private function fixture():array{$t=new UmkmDisbursementCancellationTest('test_owner_cancels_requested_and_releases_once');$ref=new \ReflectionMethod($t,'fixture');$ref->setAccessible(true);[$owner,$d,$e]=$ref->invoke($t);$d->update(['status'=>'approved','transfer_recorded_by'=>User::factory()->create(['role'=>'admin_bumdes'])->id,'transfer_reference'=>'ORIG','transfer_proof_path'=>'original.pdf']);return[User::factory()->create(['role'=>'admin_bumdes']),$d,$e];}}
